"""AFLGo's two-level target-distance computation.

Böhme, Pham, Nguyen and Roychoudhury (CCS'17) turn greybox fuzzing into a
*directed* search by giving every seed a numeric **distance** to a set of
target locations and then spending the mutation budget preferentially on
the seeds that are close.  Computing that distance is a static, one-off
analysis with two levels:

1. **Function level.**  On the call graph ``CG``, ``d_f(n, T_f)`` is the
   number of call edges on the shortest path from function ``n`` to the
   nearest target function.  It is obtained with a single BFS on the
   *reverse* call graph seeded at the target functions
   (:meth:`CallGraph.distances_to`).

2. **Basic-block level.**  Inside a function, ``d_b(m, T_b)`` is defined
   recursively (paper, eq. 2/3), with ``N(m)`` the set of basic blocks that
   call a function with a defined ``d_f``::

       d_b(m, T_b) = 0                                        if m in T_b
                   = c * min_{n in N(m)} d_f(n, T_f)          if m calls n
                   = H({ d_b(m, m') + d_b(m', T_b) : m' in N(m) })   otherwise

   ``H`` is the **harmonic mean** -- a block with many short routes to the
   targets is considered closer than a block with a single route of the same
   average length, and a single infinite term does not poison the result the
   way an arithmetic mean would.  ``c`` (:data:`CALL_PENALTY`) converts call
   edges into basic-block units.

A program that the simulator models as one flat CFG has an empty ``N(m)``
for every block, so the recursion collapses onto the intra-procedural BFS
distance to the nearest target -- which is exactly the interprocedural
shortest path.  That identity is what
:meth:`DistanceComputer.ground_truth_accuracy` checks, against the
independent BFS in :mod:`fuzzsim.program_model`.

Finally the raw distances are **normalised** to ``[0, 1]``
(:func:`normalize_distances`) because the annealing-based power schedule in
:mod:`fuzzsim.aflgo_annealing` multiplies by ``1 - d(s)`` and therefore
needs a scale-free quantity.

Determinism: this module is pure graph arithmetic; no randomness at all.
"""

from __future__ import annotations

from collections import deque
from dataclasses import dataclass, field
from enum import Enum
from typing import (Any, Dict, Iterable, List, Mapping, Optional, Sequence,
                    Set, Tuple)

INF = float("inf")

#: ``c`` of the paper: how many basic-block steps one call edge is worth.
#: AFLGo uses 10 so that a function that is one call away always ranks
#: behind every block of the current function.
CALL_PENALTY = 10.0

#: Distance assigned to a seed that reaches nothing target-related.  Kept
#: finite so that the normalisation and the power schedule stay defined;
#: after normalisation it is exactly 1.0 (the worst possible seed).
UNREACHABLE_DISTANCE = INF


# --------------------------------------------------------------------------
# Means
# --------------------------------------------------------------------------

def harmonic_mean(values: Iterable[float]) -> float:
    """Harmonic mean ``n / sum(1/x)`` over the *finite, positive* entries.

    Infinite entries contribute ``1/inf == 0`` to the sum and are dropped
    from ``n`` as well, so an unreachable route simply does not count; a
    zero entry means "already at the target" and short-circuits to 0.
    """
    finite: List[float] = []
    for value in values:
        v = float(value)
        if v <= 0.0:
            return 0.0
        if v < INF:
            finite.append(v)
    if not finite:
        return INF
    return len(finite) / sum(1.0 / v for v in finite)


def inverse_sum(values: Iterable[float]) -> float:
    """The paper's raw ``[sum x^-1]^-1`` combination (harmonic mean / n).

    Kept alongside :func:`harmonic_mean` because AFLGo's own implementation
    uses this un-normalised form; the two induce the same ordering only
    when every block reaches the same number of routes.
    """
    total = 0.0
    for value in values:
        v = float(value)
        if v <= 0.0:
            return 0.0
        if v < INF:
            total += 1.0 / v
    if total <= 0.0:
        return INF
    return 1.0 / total


def arithmetic_mean(values: Iterable[float]) -> float:
    """Plain mean over finite entries (INF if there are none)."""
    finite = [float(v) for v in values if float(v) < INF]
    if not finite:
        return INF
    return sum(finite) / len(finite)


class Aggregation(str, Enum):
    """How several candidate distances are folded into one."""

    MIN = "min"
    HARMONIC = "harmonic"
    MEAN = "mean"
    INVERSE_SUM = "inverse_sum"


def aggregate(values: Sequence[float], mode: Aggregation) -> float:
    """Fold ``values`` with the requested aggregation."""
    mode = Aggregation(mode)
    if not values:
        return INF
    if mode is Aggregation.MIN:
        return min(float(v) for v in values)
    if mode is Aggregation.HARMONIC:
        return harmonic_mean(values)
    if mode is Aggregation.INVERSE_SUM:
        return inverse_sum(values)
    return arithmetic_mean(values)


# --------------------------------------------------------------------------
# Call graph
# --------------------------------------------------------------------------

class CallGraph:
    """The program's call graph, with reverse-BFS distances to targets.

    Nodes are function names, edges are "``caller`` may call ``callee``".
    The class is deliberately tiny: AFLGo only ever needs the reverse BFS
    and a couple of reachability queries.
    """

    def __init__(self, functions: Optional[Iterable[str]] = None):
        self._callees: Dict[str, Set[str]] = {}
        self._callers: Dict[str, Set[str]] = {}
        for name in functions or []:
            self.add_function(name)

    # -- construction -----------------------------------------------------
    def add_function(self, name: str) -> str:
        """Register a function (idempotent)."""
        self._callees.setdefault(name, set())
        self._callers.setdefault(name, set())
        return name

    def add_call(self, caller: str, callee: str) -> None:
        """Register a call edge ``caller -> callee`` (creating both nodes)."""
        self.add_function(caller)
        self.add_function(callee)
        self._callees[caller].add(callee)
        self._callers[callee].add(caller)

    def remove_call(self, caller: str, callee: str) -> bool:
        """Drop a call edge; returns whether it existed."""
        if callee in self._callees.get(caller, ()):
            self._callees[caller].discard(callee)
            self._callers[callee].discard(caller)
            return True
        return False

    # -- queries ----------------------------------------------------------
    @property
    def functions(self) -> List[str]:
        return sorted(self._callees)

    def callees(self, name: str) -> List[str]:
        return sorted(self._callees.get(name, ()))

    def callers(self, name: str) -> List[str]:
        return sorted(self._callers.get(name, ()))

    def __contains__(self, name: object) -> bool:
        return name in self._callees

    def __len__(self) -> int:
        return len(self._callees)

    def edge_count(self) -> int:
        return sum(len(v) for v in self._callees.values())

    # -- distances --------------------------------------------------------
    def distances_to(self, targets: Iterable[str]) -> Dict[str, float]:
        """``d_f(n, T_f)`` for every function: BFS on the *reverse* CG.

        Walking the reverse graph from the targets computes, in one sweep,
        the distance of every function to the nearest target instead of
        running a forward search per function.
        """
        dist: Dict[str, float] = {name: INF for name in self._callees}
        queue: deque = deque()
        for target in targets:
            if target in dist:
                dist[target] = 0.0
                queue.append(target)
        while queue:
            node = queue.popleft()
            for caller in sorted(self._callers.get(node, ())):
                if dist[caller] > dist[node] + 1.0:
                    dist[caller] = dist[node] + 1.0
                    queue.append(caller)
        return dist

    def distance(self, name: str, targets: Iterable[str]) -> float:
        """``d_f(name, T_f)`` for a single function."""
        return self.distances_to(targets).get(name, INF)

    def reaches(self, name: str, target: str) -> bool:
        """Whether ``target`` is callable (transitively) from ``name``."""
        return self.distances_to([target]).get(name, INF) < INF

    def stats(self) -> Dict[str, Any]:
        return {
            "functions": len(self._callees),
            "call_edges": self.edge_count(),
            "leaves": sum(1 for f, c in self._callees.items() if not c),
            "roots": sum(1 for f, c in self._callers.items() if not c),
        }


# --------------------------------------------------------------------------
# Control flow graph
# --------------------------------------------------------------------------

class CFGDistance:
    """Intra-procedural shortest-path distances over a basic-block CFG.

    All CFG edges have weight 1, so BFS is enough; both directions are kept
    because AFLGo needs "distance *from* a block" (to reach a call site) and
    "distance *to* the targets".
    """

    def __init__(self,
                 blocks: Iterable[int],
                 edges: Iterable[Tuple[int, int]]):
        self.blocks: List[int] = sorted({int(b) for b in blocks})
        self.succ: Dict[int, Set[int]] = {b: set() for b in self.blocks}
        self.pred: Dict[int, Set[int]] = {b: set() for b in self.blocks}
        self.edges: List[Tuple[int, int]] = []
        for src, dst in edges:
            self.add_edge(int(src), int(dst))

    # -- construction -----------------------------------------------------
    def add_block(self, block: int) -> None:
        if block not in self.succ:
            self.blocks = sorted(self.blocks + [block])
            self.succ[block] = set()
            self.pred[block] = set()

    def add_edge(self, src: int, dst: int) -> None:
        self.add_block(src)
        self.add_block(dst)
        if dst not in self.succ[src]:
            self.succ[src].add(dst)
            self.pred[dst].add(src)
            self.edges.append((src, dst))

    # -- BFS --------------------------------------------------------------
    def _bfs(self, sources: Iterable[int],
             adjacency: Mapping[int, Set[int]]) -> Dict[int, float]:
        dist: Dict[int, float] = {b: INF for b in self.blocks}
        queue: deque = deque()
        for src in sources:
            if src in dist:
                dist[src] = 0.0
                queue.append(src)
        while queue:
            node = queue.popleft()
            for nxt in sorted(adjacency.get(node, ())):
                if dist[nxt] > dist[node] + 1.0:
                    dist[nxt] = dist[node] + 1.0
                    queue.append(nxt)
        return dist

    def distances_to(self, targets: Iterable[int]) -> Dict[int, float]:
        """Distance from every block to the nearest block in ``targets``."""
        return self._bfs(targets, self.pred)

    def distances_from(self, source: int) -> Dict[int, float]:
        """Distance from ``source`` to every block."""
        return self._bfs([source], self.succ)

    def shortest_path_length(self, src: int, dst: int) -> float:
        """Number of CFG edges on the shortest ``src -> dst`` path."""
        return self.distances_from(src).get(dst, INF)

    def reachable_from(self, source: int) -> Set[int]:
        return {b for b, d in self.distances_from(source).items() if d < INF}

    def stats(self) -> Dict[str, Any]:
        return {"blocks": len(self.blocks), "edges": len(self.edges)}


# --------------------------------------------------------------------------
# Normalisation
# --------------------------------------------------------------------------

def normalize_distances(distances: Mapping[Any, float],
                        unreachable: float = 1.0) -> Dict[Any, float]:
    """Min-max scale finite distances into ``[0, 1]``.

    ``0`` is "at a target", ``1`` is "as far as anything gets".  Unreachable
    entries are mapped to ``unreachable`` (1.0 by default: worst possible).
    If every reachable block is equidistant the map is constant 0, since no
    seed is then closer than any other.
    """
    finite = [float(v) for v in distances.values() if float(v) < INF]
    if not finite:
        return {k: unreachable for k in distances}
    lo, hi = min(finite), max(finite)
    span = hi - lo
    out: Dict[Any, float] = {}
    for key, value in distances.items():
        v = float(value)
        if v >= INF:
            out[key] = unreachable
        elif span <= 0.0:
            out[key] = 0.0
        else:
            out[key] = (v - lo) / span
    return out


def normalize_value(value: float, lo: float, hi: float,
                    unreachable: float = 1.0) -> float:
    """Scale a single distance with a pre-computed ``[lo, hi]`` range."""
    v = float(value)
    if v >= INF:
        return unreachable
    if hi - lo <= 0.0:
        return 0.0
    return min(1.0, max(0.0, (v - lo) / (hi - lo)))


# --------------------------------------------------------------------------
# The orchestrator
# --------------------------------------------------------------------------

@dataclass
class FunctionModel:
    """One function of the modelled program.

    ``blocks`` are its basic blocks, ``entry`` its entry block and
    ``call_sites`` maps a block to the function it calls.  A program the
    simulator exposes as a single flat CFG is modelled as one function with
    no call sites, which is the degenerate -- and exact -- case.
    """

    name: str
    blocks: List[int]
    entry: int
    call_sites: Dict[int, str] = field(default_factory=dict)


class DistanceComputer:
    """Full AFLGo distance pipeline for a :class:`SimulatedProgram`.

    Usage::

        dc = DistanceComputer(program, targets=[17, 19])
        dc.compute()                 # raw d_b for every block
        dc.normalized_block_distances()
        dc.seed_distance(covered_edges)

    ``functions`` is optional: without it the whole program is one function
    and the block distances are plain BFS distances; with it the two-level
    formula of the paper is evaluated, using ``aggregation`` (harmonic mean
    by default) to fold the routes through several call sites.
    """

    def __init__(self,
                 program: Any,
                 targets: Optional[Sequence[int]] = None,
                 functions: Optional[Sequence[FunctionModel]] = None,
                 aggregation: Aggregation = Aggregation.HARMONIC,
                 call_penalty: float = CALL_PENALTY,
                 seed_aggregation: Aggregation = Aggregation.MIN):
        self.program = program
        self.targets: List[int] = sorted(
            int(t) for t in (targets if targets is not None
                             else getattr(program, "target_blocks", []) or []))
        self.aggregation = Aggregation(aggregation)
        self.seed_aggregation = Aggregation(seed_aggregation)
        self.call_penalty = float(call_penalty)

        edges = list(getattr(program, "edges", []))
        self.edge_endpoints: Dict[int, Tuple[int, int]] = {
            int(e.edge_id): (int(e.src), int(e.dst)) for e in edges}
        block_ids = sorted(getattr(program, "blocks", {}))
        if not block_ids:
            block_ids = sorted({s for s, _ in self.edge_endpoints.values()} |
                               {d for _, d in self.edge_endpoints.values()})

        self.cfg = CFGDistance(block_ids,
                               [(s, d) for s, d in self.edge_endpoints.values()])

        self.functions: List[FunctionModel] = list(functions or [])
        if not self.functions:
            entry = int(getattr(program, "entry_block", block_ids[0] if block_ids else 0))
            self.functions = [FunctionModel(name="main", blocks=list(block_ids),
                                            entry=entry)]
        self.block_function: Dict[int, str] = {
            b: fn.name for fn in self.functions for b in fn.blocks}
        self.function_of: Dict[str, FunctionModel] = {
            fn.name: fn for fn in self.functions}

        self.call_graph = self._build_call_graph()
        self.target_functions: List[str] = sorted(
            {self.block_function[t] for t in self.targets
             if t in self.block_function})

        self.function_distances: Dict[str, float] = {}
        self.block_distances: Dict[int, float] = {}
        self._normalized: Dict[int, float] = {}
        self._edge_distances: Dict[int, float] = {}
        self._range: Tuple[float, float] = (0.0, 1.0)
        self.compute()

    # -- construction -----------------------------------------------------
    def _build_call_graph(self) -> CallGraph:
        cg = CallGraph(fn.name for fn in self.functions)
        for fn in self.functions:
            for callee in fn.call_sites.values():
                cg.add_call(fn.name, callee)
        return cg

    def _function_cfg(self, fn: FunctionModel) -> CFGDistance:
        """CFG restricted to one function's blocks."""
        inside = set(fn.blocks)
        return CFGDistance(fn.blocks,
                           [(s, d) for s, d in self.edge_endpoints.values()
                            if s in inside and d in inside])

    # -- the two-level computation ---------------------------------------
    def compute(self) -> Dict[int, float]:
        """Evaluate ``d_f`` then ``d_b`` for every block; cache and return."""
        self.function_distances = self.call_graph.distances_to(
            self.target_functions)

        if len(self.functions) == 1 and not self.functions[0].call_sites:
            # Flat model: N(m) is empty everywhere, so the recursion is just
            # the intra-procedural BFS to the nearest target.
            self.block_distances = self.cfg.distances_to(self.targets)
        else:
            self.block_distances = self._interprocedural_distances()

        self._edge_distances = {
            eid: self.block_distances.get(dst, INF)
            for eid, (_src, dst) in self.edge_endpoints.items()}
        finite = [d for d in self.block_distances.values() if d < INF]
        self._range = (min(finite), max(finite)) if finite else (0.0, 1.0)
        self._normalized = normalize_distances(self.block_distances)
        return self.block_distances

    def _interprocedural_distances(self) -> Dict[int, float]:
        """Paper eq. 2/3 evaluated per function."""
        distances: Dict[int, float] = {}
        target_set = set(self.targets)
        for fn in self.functions:
            cfg = self._function_cfg(fn)
            # Call sites whose callee can reach a target function at all.
            routes: Dict[int, float] = {}
            for block, callee in sorted(fn.call_sites.items()):
                d_f = self.function_distances.get(callee, INF)
                if d_f < INF:
                    routes[block] = self.call_penalty * d_f
            # Targets inside this function are routes of length 0.
            for block in sorted(target_set & set(fn.blocks)):
                routes[block] = 0.0

            if not routes:
                for block in fn.blocks:
                    distances[block] = INF
                continue

            per_route = {block: cfg.distances_to([block]) for block in routes}
            for block in fn.blocks:
                if block in target_set:
                    distances[block] = 0.0
                elif block in fn.call_sites and block in routes:
                    distances[block] = routes[block]
                else:
                    candidates = [per_route[r][block] + routes[r]
                                  for r in routes
                                  if per_route[r].get(block, INF) < INF]
                    distances[block] = aggregate(candidates, self.aggregation)
        return distances

    # -- accessors --------------------------------------------------------
    def block_distance(self, block: int) -> float:
        return self.block_distances.get(int(block), INF)

    def normalized_block_distances(self) -> Dict[int, float]:
        return dict(self._normalized)

    def normalized_block_distance(self, block: int) -> float:
        return self._normalized.get(int(block), 1.0)

    def edge_distance(self, edge_id: int) -> float:
        """Distance of the block an edge lands in."""
        return self._edge_distances.get(int(edge_id), INF)

    def edge_distances(self) -> Dict[int, float]:
        return dict(self._edge_distances)

    def distance_range(self) -> Tuple[float, float]:
        return self._range

    # -- seed distance ----------------------------------------------------
    def seed_distance(self, covered_edges: Iterable[int],
                      mode: Optional[Aggregation] = None) -> float:
        """``d(s, T_b)`` from the edges a seed covered.

        The default aggregation is the **minimum** block distance among the
        covered edges: a seed is as close to the target as the closest point
        its execution reached.  ``mean`` (the paper's own choice) and
        ``harmonic`` are available for comparison.
        """
        mode = self.seed_aggregation if mode is None else Aggregation(mode)
        values = [self._edge_distances.get(int(e), INF) for e in covered_edges]
        values = [v for v in values if v < INF]
        if not values:
            return INF
        return aggregate(values, mode)

    def normalized_seed_distance(self, covered_edges: Iterable[int],
                                 mode: Optional[Aggregation] = None) -> float:
        """Seed distance scaled into ``[0, 1]`` (1.0 = reaches nothing)."""
        lo, hi = self._range
        return normalize_value(self.seed_distance(covered_edges, mode), lo, hi)

    # -- validation -------------------------------------------------------
    def ground_truth_distances(self) -> Dict[int, float]:
        """Reference distances from :mod:`fuzzsim.program_model`'s own BFS."""
        getter = getattr(self.program, "get_shortest_distances", None)
        if getter is None:
            return {}
        return getter(self.targets)

    def ground_truth_accuracy(self, tolerance: float = 1e-9) -> float:
        """Percentage of blocks whose computed distance matches the reference.

        The reference is the interprocedural shortest path computed by the
        base package (:meth:`SimulatedProgram.get_shortest_distances`), which
        is an implementation independent of everything in this module.  For
        the flat single-function model the two-level formula must reproduce
        it exactly, so anything below 100% is a bug in the BFS, in the
        aggregation or in the unreachable handling.
        """
        truth = self.ground_truth_distances()
        if not truth:
            return 0.0
        agree = 0
        for block, expected in truth.items():
            got = self.block_distances.get(block, INF)
            if expected >= INF and got >= INF:
                agree += 1
            elif abs(got - expected) <= tolerance:
                agree += 1
        return agree / len(truth) * 100.0

    def disagreements(self, tolerance: float = 1e-9) -> Dict[int, Tuple[float, float]]:
        """``{block: (computed, expected)}`` for every mismatching block."""
        truth = self.ground_truth_distances()
        out: Dict[int, Tuple[float, float]] = {}
        for block, expected in truth.items():
            got = self.block_distances.get(block, INF)
            if expected >= INF and got >= INF:
                continue
            if abs(got - expected) > tolerance:
                out[block] = (got, expected)
        return out

    # -- reporting --------------------------------------------------------
    def stats(self) -> Dict[str, Any]:
        finite = [d for d in self.block_distances.values() if d < INF]
        return {
            "targets": list(self.targets),
            "target_functions": list(self.target_functions),
            "aggregation": self.aggregation.value,
            "seed_aggregation": self.seed_aggregation.value,
            "blocks": len(self.block_distances),
            "reachable_blocks": len(finite),
            "min_distance": min(finite) if finite else INF,
            "max_distance": max(finite) if finite else INF,
            "mean_distance": (sum(finite) / len(finite)) if finite else INF,
            "call_graph": self.call_graph.stats(),
            "cfg": self.cfg.stats(),
            "accuracy": self.ground_truth_accuracy(),
        }

toolUseResult.content:
"""AFLGo's two-level target-distance computation.

Böhme, Pham, Nguyen and Roychoudhury (CCS'17) turn greybox fuzzing into a
*directed* search by giving every seed a numeric **distance** to a set of
target locations and then spending the mutation budget preferentially on
the seeds that are close.  Computing that distance is a static, one-off
analysis with two levels:

1. **Function level.**  On the call graph ``CG``, ``d_f(n, T_f)`` is the
   number of call edges on the shortest path from function ``n`` to the
   nearest target function.  It is obtained with a single BFS on the
   *reverse* call graph seeded at the target functions
   (:meth:`CallGraph.distances_to`).

2. **Basic-block level.**  Inside a function, ``d_b(m, T_b)`` is defined
   recursively (paper, eq. 2/3), with ``N(m)`` the set of basic blocks that
   call a function with a defined ``d_f``::

       d_b(m, T_b) = 0                                        if m in T_b
                   = c * min_{n in N(m)} d_f(n, T_f)          if m calls n
                   = H({ d_b(m, m') + d_b(m', T_b) : m' in N(m) })   otherwise

   ``H`` is the **harmonic mean** -- a block with many short routes to the
   targets is considered closer than a block with a single route of the same
   average length, and a single infinite term does not poison the result the
   way an arithmetic mean would.  ``c`` (:data:`CALL_PENALTY`) converts call
   edges into basic-block units.

A program that the simulator models as one flat CFG has an empty ``N(m)``
for every block, so the recursion collapses onto the intra-procedural BFS
distance to the nearest target -- which is exactly the interprocedural
shortest path.  That identity is what
:meth:`DistanceComputer.ground_truth_accuracy` checks, against the
independent BFS in :mod:`fuzzsim.program_model`.

Finally the raw distances are **normalised** to ``[0, 1]``
(:func:`normalize_distances`) because the annealing-based power schedule in
:mod:`fuzzsim.aflgo_annealing` multiplies by ``1 - d(s)`` and therefore
needs a scale-free quantity.

Determinism: this module is pure graph arithmetic; no randomness at all.
"""

from __future__ import annotations

from collections import deque
from dataclasses import dataclass, field
from enum import Enum
from typing import (Any, Dict, Iterable, List, Mapping, Optional, Sequence,
                    Set, Tuple)

INF = float("inf")

#: ``c`` of the paper: how many basic-block steps one call edge is worth.
#: AFLGo uses 10 so that a function that is one call away always ranks
#: behind every block of the current function.
CALL_PENALTY = 10.0

#: Distance assigned to a seed that reaches nothing target-related.  Kept
#: finite so that the normalisation and the power schedule stay defined;
#: after normalisation it is exactly 1.0 (the worst possible seed).
UNREACHABLE_DISTANCE = INF


# --------------------------------------------------------------------------
# Means
# --------------------------------------------------------------------------

def harmonic_mean(values: Iterable[float]) -> float:
    """Harmonic mean ``n / sum(1/x)`` over the *finite, positive* entries.

    Infinite entries contribute ``1/inf == 0`` to the sum and are dropped
    from ``n`` as well, so an unreachable route simply does not count; a
    zero entry means "already at the target" and short-circuits to 0.
    """
    finite: List[float] = []
    for value in values:
        v = float(value)
        if v <= 0.0:
            return 0.0
        if v < INF:
            finite.append(v)
    if not finite:
        return INF
    return len(finite) / sum(1.0 / v for v in finite)


def inverse_sum(values: Iterable[float]) -> float:
    """The paper's raw ``[sum x^-1]^-1`` combination (harmonic mean / n).

    Kept alongside :func:`harmonic_mean` because AFLGo's own implementation
    uses this un-normalised form; the two induce the same ordering only
    when every block reaches the same number of routes.
    """
    total = 0.0
    for value in values:
        v = float(value)
        if v <= 0.0:
            return 0.0
        if v < INF:
            total += 1.0 / v
    if total <= 0.0:
        return INF
    return 1.0 / total


def arithmetic_mean(values: Iterable[float]) -> float:
    """Plain mean over finite entries (INF if there are none)."""
    finite = [float(v) for v in values if float(v) < INF]
    if not finite:
        return INF
    return sum(finite) / len(finite)


class Aggregation(str, Enum):
    """How several candidate distances are folded into one."""

    MIN = "min"
    HARMONIC = "harmonic"
    MEAN = "mean"
    INVERSE_SUM = "inverse_sum"


def aggregate(values: Sequence[float], mode: Aggregation) -> float:
    """Fold ``values`` with the requested aggregation."""
    mode = Aggregation(mode)
    if not values:
        return INF
    if mode is Aggregation.MIN:
        return min(float(v) for v in values)
    if mode is Aggregation.HARMONIC:
        return harmonic_mean(values)
    if mode is Aggregation.INVERSE_SUM:
        return inverse_sum(values)
    return arithmetic_mean(values)


# --------------------------------------------------------------------------
# Call graph
# --------------------------------------------------------------------------

class CallGraph:
    """The program's call graph, with reverse-BFS distances to targets.

    Nodes are function names, edges are "``caller`` may call ``callee``".
    The class is deliberately tiny: AFLGo only ever needs the reverse BFS
    and a couple of reachability queries.
    """

    def __init__(self, functions: Optional[Iterable[str]] = None):
        self._callees: Dict[str, Set[str]] = {}
        self._callers: Dict[str, Set[str]] = {}
        for name in functions or []:
            self.add_function(name)

    # -- construction -----------------------------------------------------
    def add_function(self, name: str) -> str:
        """Register a function (idempotent)."""
        self._callees.setdefault(name, set())
        self._callers.setdefault(name, set())
        return name

    def add_call(self, caller: str, callee: str) -> None:
        """Register a call edge ``caller -> callee`` (creating both nodes)."""
        self.add_function(caller)
        self.add_function(callee)
        self._callees[caller].add(callee)
        self._callers[callee].add(caller)

    def remove_call(self, caller: str, callee: str) -> bool:
        """Drop a call edge; returns whether it existed."""
        if callee in self._callees.get(caller, ()):
            self._callees[caller].discard(callee)
            self._callers[callee].discard(caller)
            return True
        return False

    # -- queries ----------------------------------------------------------
    @property
    def functions(self) -> List[str]:
        return sorted(self._callees)

    def callees(self, name: str) -> List[str]:
        return sorted(self._callees.get(name, ()))

    def callers(self, name: str) -> List[str]:
        return sorted(self._callers.get(name, ()))

    def __contains__(self, name: object) -> bool:
        return name in self._callees

    def __len__(self) -> int:
        return len(self._callees)

    def edge_count(self) -> int:
        return sum(len(v) for v in self._callees.values())

    # -- distances --------------------------------------------------------
    def distances_to(self, targets: Iterable[str]) -> Dict[str, float]:
        """``d_f(n, T_f)`` for every function: BFS on the *reverse* CG.

        Walking the reverse graph from the targets computes, in one sweep,
        the distance of every function to the nearest target instead of
        running a forward search per function.
        """
        dist: Dict[str, float] = {name: INF for name in self._callees}
        queue: deque = deque()
        for target in targets:
            if target in dist:
                dist[target] = 0.0
                queue.append(target)
        while queue:
            node = queue.popleft()
            for caller in sorted(self._callers.get(node, ())):
                if dist[caller] > dist[node] + 1.0:
                    dist[caller] = dist[node] + 1.0
                    queue.append(caller)
        return dist

    def distance(self, name: str, targets: Iterable[str]) -> float:
        """``d_f(name, T_f)`` for a single function."""
        return self.distances_to(targets).get(name, INF)

    def reaches(self, name: str, target: str) -> bool:
        """Whether ``target`` is callable (transitively) from ``name``."""
        return self.distances_to([target]).get(name, INF) < INF

    def stats(self) -> Dict[str, Any]:
        return {
            "functions": len(self._callees),
            "call_edges": self.edge_count(),
            "leaves": sum(1 for f, c in self._callees.items() if not c),
            "roots": sum(1 for f, c in self._callers.items() if not c),
        }


# --------------------------------------------------------------------------
# Control flow graph
# --------------------------------------------------------------------------

class CFGDistance:
    """Intra-procedural shortest-path distances over a basic-block CFG.

    All CFG edges have weight 1, so BFS is enough; both directions are kept
    because AFLGo needs "distance *from* a block" (to reach a call site) and
    "distance *to* the targets".
    """

    def __init__(self,
                 blocks: Iterable[int],
                 edges: Iterable[Tuple[int, int]]):
        self.blocks: List[int] = sorted({int(b) for b in blocks})
        self.succ: Dict[int, Set[int]] = {b: set() for b in self.blocks}
        self.pred: Dict[int, Set[int]] = {b: set() for b in self.blocks}
        self.edges: List[Tuple[int, int]] = []
        for src, dst in edges:
            self.add_edge(int(src), int(dst))

    # -- construction -----------------------------------------------------
    def add_block(self, block: int) -> None:
        if block not in self.succ:
            self.blocks = sorted(self.blocks + [block])
            self.succ[block] = set()
            self.pred[block] = set()

    def add_edge(self, src: int, dst: int) -> None:
        self.add_block(src)
        self.add_block(dst)
        if dst not in self.succ[src]:
            self.succ[src].add(dst)
            self.pred[dst].add(src)
            self.edges.append((src, dst))

    # -- BFS --------------------------------------------------------------
    def _bfs(self, sources: Iterable[int],
             adjacency: Mapping[int, Set[int]]) -> Dict[int, float]:
        dist: Dict[int, float] = {b: INF for b in self.blocks}
        queue: deque = deque()
        for src in sources:
            if src in dist:
                dist[src] = 0.0
                queue.append(src)
        while queue:
            node = queue.popleft()
            for nxt in sorted(adjacency.get(node, ())):
                if dist[nxt] > dist[node] + 1.0:
                    dist[nxt] = dist[node] + 1.0
                    queue.append(nxt)
        return dist

    def distances_to(self, targets: Iterable[int]) -> Dict[int, float]:
        """Distance from every block to the nearest block in ``targets``."""
        return self._bfs(targets, self.pred)

    def distances_from(self, source: int) -> Dict[int, float]:
        """Distance from ``source`` to every block."""
        return self._bfs([source], self.succ)

    def shortest_path_length(self, src: int, dst: int) -> float:
        """Number of CFG edges on the shortest ``src -> dst`` path."""
        return self.distances_from(src).get(dst, INF)

    def reachable_from(self, source: int) -> Set[int]:
        return {b for b, d in self.distances_from(source).items() if d < INF}

    def stats(self) -> Dict[str, Any]:
        return {"blocks": len(self.blocks), "edges": len(self.edges)}


# --------------------------------------------------------------------------
# Normalisation
# --------------------------------------------------------------------------

def normalize_distances(distances: Mapping[Any, float],
                        unreachable: float = 1.0) -> Dict[Any, float]:
    """Min-max scale finite distances into ``[0, 1]``.

    ``0`` is "at a target", ``1`` is "as far as anything gets".  Unreachable
    entries are mapped to ``unreachable`` (1.0 by default: worst possible).
    If every reachable block is equidistant the map is constant 0, since no
    seed is then closer than any other.
    """
    finite = [float(v) for v in distances.values() if float(v) < INF]
    if not finite:
        return {k: unreachable for k in distances}
    lo, hi = min(finite), max(finite)
    span = hi - lo
    out: Dict[Any, float] = {}
    for key, value in distances.items():
        v = float(value)
        if v >= INF:
            out[key] = unreachable
        elif span <= 0.0:
            out[key] = 0.0
        else:
            out[key] = (v - lo) / span
    return out


def normalize_value(value: float, lo: float, hi: float,
                    unreachable: float = 1.0) -> float:
    """Scale a single distance with a pre-computed ``[lo, hi]`` range."""
    v = float(value)
    if v >= INF:
        return unreachable
    if hi - lo <= 0.0:
        return 0.0
    return min(1.0, max(0.0, (v - lo) / (hi - lo)))


# --------------------------------------------------------------------------
# The orchestrator
# --------------------------------------------------------------------------

@dataclass
class FunctionModel:
    """One function of the modelled program.

    ``blocks`` are its basic blocks, ``entry`` its entry block and
    ``call_sites`` maps a block to the function it calls.  A program the
    simulator exposes as a single flat CFG is modelled as one function with
    no call sites, which is the degenerate -- and exact -- case.
    """

    name: str
    blocks: List[int]
    entry: int
    call_sites: Dict[int, str] = field(default_factory=dict)


class DistanceComputer:
    """Full AFLGo distance pipeline for a :class:`SimulatedProgram`.

    Usage::

        dc = DistanceComputer(program, targets=[17, 19])
        dc.compute()                 # raw d_b for every block
        dc.normalized_block_distances()
        dc.seed_distance(covered_edges)

    ``functions`` is optional: without it the whole program is one function
    and the block distances are plain BFS distances; with it the two-level
    formula of the paper is evaluated, using ``aggregation`` (harmonic mean
    by default) to fold the routes through several call sites.
    """

    def __init__(self,
                 program: Any,
                 targets: Optional[Sequence[int]] = None,
                 functions: Optional[Sequence[FunctionModel]] = None,
                 aggregation: Aggregation = Aggregation.HARMONIC,
                 call_penalty: float = CALL_PENALTY,
                 seed_aggregation: Aggregation = Aggregation.MIN):
        self.program = program
        self.targets: List[int] = sorted(
            int(t) for t in (targets if targets is not None
                             else getattr(program, "target_blocks", []) or []))
        self.aggregation = Aggregation(aggregation)
        self.seed_aggregation = Aggregation(seed_aggregation)
        self.call_penalty = float(call_penalty)

        edges = list(getattr(program, "edges", []))
        self.edge_endpoints: Dict[int, Tuple[int, int]] = {
            int(e.edge_id): (int(e.src), int(e.dst)) for e in edges}
        block_ids = sorted(getattr(program, "blocks", {}))
        if not block_ids:
            block_ids = sorted({s for s, _ in self.edge_endpoints.values()} |
                               {d for _, d in self.edge_endpoints.values()})

        self.cfg = CFGDistance(block_ids,
                               [(s, d) for s, d in self.edge_endpoints.values()])

        self.functions: List[FunctionModel] = list(functions or [])
        if not self.functions:
            entry = int(getattr(program, "entry_block", block_ids[0] if block_ids else 0))
            self.functions = [FunctionModel(name="main", blocks=list(block_ids),
                                            entry=entry)]
        self.block_function: Dict[int, str] = {
            b: fn.name for fn in self.functions for b in fn.blocks}
        self.function_of: Dict[str, FunctionModel] = {
            fn.name: fn for fn in self.functions}

        self.call_graph = self._build_call_graph()
        self.target_functions: List[str] = sorted(
            {self.block_function[t] for t in self.targets
             if t in self.block_function})

        self.function_distances: Dict[str, float] = {}
        self.block_distances: Dict[int, float] = {}
        self._normalized: Dict[int, float] = {}
        self._edge_distances: Dict[int, float] = {}
        self._range: Tuple[float, float] = (0.0, 1.0)
        self.compute()

    # -- construction -----------------------------------------------------
    def _build_call_graph(self) -> CallGraph:
        cg = CallGraph(fn.name for fn in self.functions)
        for fn in self.functions:
            for callee in fn.call_sites.values():
                cg.add_call(fn.name, callee)
        return cg

    def _function_cfg(self, fn: FunctionModel) -> CFGDistance:
        """CFG restricted to one function's blocks."""
        inside = set(fn.blocks)
        return CFGDistance(fn.blocks,
                           [(s, d) for s, d in self.edge_endpoints.values()
                            if s in inside and d in inside])

    # -- the two-level computation ---------------------------------------
    def compute(self) -> Dict[int, float]:
        """Evaluate ``d_f`` then ``d_b`` for every block; cache and return."""
        self.function_distances = self.call_graph.distances_to(
            self.target_functions)

        if len(self.functions) == 1 and not self.functions[0].call_sites:
            # Flat model: N(m) is empty everywhere, so the recursion is just
            # the intra-procedural BFS to the nearest target.
            self.block_distances = self.cfg.distances_to(self.targets)
        else:
            self.block_distances = self._interprocedural_distances()

        self._edge_distances = {
            eid: self.block_distances.get(dst, INF)
            for eid, (_src, dst) in self.edge_endpoints.items()}
        finite = [d for d in self.block_distances.values() if d < INF]
        self._range = (min(finite), max(finite)) if finite else (0.0, 1.0)
        self._normalized = normalize_distances(self.block_distances)
        return self.block_distances

    def _interprocedural_distances(self) -> Dict[int, float]:
        """Paper eq. 2/3 evaluated per function."""
        distances: Dict[int, float] = {}
        target_set = set(self.targets)
        for fn in self.functions:
            cfg = self._function_cfg(fn)
            # Call sites whose callee can reach a target function at all.
            routes: Dict[int, float] = {}
            for block, callee in sorted(fn.call_sites.items()):
                d_f = self.function_distances.get(callee, INF)
                if d_f < INF:
                    routes[block] = self.call_penalty * d_f
            # Targets inside this function are routes of length 0.
            for block in sorted(target_set & set(fn.blocks)):
                routes[block] = 0.0

            if not routes:
                for block in fn.blocks:
                    distances[block] = INF
                continue

            per_route = {block: cfg.distances_to([block]) for block in routes}
            for block in fn.blocks:
                if block in target_set:
                    distances[block] = 0.0
                elif block in fn.call_sites and block in routes:
                    distances[block] = routes[block]
                else:
                    candidates = [per_route[r][block] + routes[r]
                                  for r in routes
                                  if per_route[r].get(block, INF) < INF]
                    distances[block] = aggregate(candidates, self.aggregation)
        return distances

    # -- accessors --------------------------------------------------------
    def block_distance(self, block: int) -> float:
        return self.block_distances.get(int(block), INF)

    def normalized_block_distances(self) -> Dict[int, float]:
        return dict(self._normalized)

    def normalized_block_distance(self, block: int) -> float:
        return self._normalized.get(int(block), 1.0)

    def edge_distance(self, edge_id: int) -> float:
        """Distance of the block an edge lands in."""
        return self._edge_distances.get(int(edge_id), INF)

    def edge_distances(self) -> Dict[int, float]:
        return dict(self._edge_distances)

    def distance_range(self) -> Tuple[float, float]:
        return self._range

    # -- seed distance ----------------------------------------------------
    def seed_distance(self, covered_edges: Iterable[int],
                      mode: Optional[Aggregation] = None) -> float:
        """``d(s, T_b)`` from the edges a seed covered.

        The default aggregation is the **minimum** block distance among the
        covered edges: a seed is as close to the target as the closest point
        its execution reached.  ``mean`` (the paper's own choice) and
        ``harmonic`` are available for comparison.
        """
        mode = self.seed_aggregation if mode is None else Aggregation(mode)
        values = [self._edge_distances.get(int(e), INF) for e in covered_edges]
        values = [v for v in values if v < INF]
        if not values:
            return INF
        return aggregate(values, mode)

    def normalized_seed_distance(self, covered_edges: Iterable[int],
                                 mode: Optional[Aggregation] = None) -> float:
        """Seed distance scaled into ``[0, 1]`` (1.0 = reaches nothing)."""
        lo, hi = self._range
        return normalize_value(self.seed_distance(covered_edges, mode), lo, hi)

    # -- validation -------------------------------------------------------
    def ground_truth_distances(self) -> Dict[int, float]:
        """Reference distances from :mod:`fuzzsim.program_model`'s own BFS."""
        getter = getattr(self.program, "get_shortest_distances", None)
        if getter is None:
            return {}
        return getter(self.targets)

    def ground_truth_accuracy(self, tolerance: float = 1e-9) -> float:
        """Percentage of blocks whose computed distance matches the reference.

        The reference is the interprocedural shortest path computed by the
        base package (:meth:`SimulatedProgram.get_shortest_distances`), which
        is an implementation independent of everything in this module.  For
        the flat single-function model the two-level formula must reproduce
        it exactly, so anything below 100% is a bug in the BFS, in the
        aggregation or in the unreachable handling.
        """
        truth = self.ground_truth_distances()
        if not truth:
            return 0.0
        agree = 0
        for block, expected in truth.items():
            got = self.block_distances.get(block, INF)
            if expected >= INF and got >= INF:
                agree += 1
            elif abs(got - expected) <= tolerance:
                agree += 1
        return agree / len(truth) * 100.0

    def disagreements(self, tolerance: float = 1e-9) -> Dict[int, Tuple[float, float]]:
        """``{block: (computed, expected)}`` for every mismatching block."""
        truth = self.ground_truth_distances()
        out: Dict[int, Tuple[float, float]] = {}
        for block, expected in truth.items():
            got = self.block_distances.get(block, INF)
            if expected >= INF and got >= INF:
                continue
            if abs(got - expected) > tolerance:
                out[block] = (got, expected)
        return out

    # -- reporting --------------------------------------------------------
    def stats(self) -> Dict[str, Any]:
        finite = [d for d in self.block_distances.values() if d < INF]
        return {
            "targets": list(self.targets),
            "target_functions": list(self.target_functions),
            "aggregation": self.aggregation.value,
            "seed_aggregation": self.seed_aggregation.value,
            "blocks": len(self.block_distances),
            "reachable_blocks": len(finite),
            "min_distance": min(finite) if finite else INF,
            "max_distance": max(finite) if finite else INF,
            "mean_distance": (sum(finite) / len(finite)) if finite else INF,
            "call_graph": self.call_graph.stats(),
            "cfg": self.cfg.stats(),
            "accuracy": self.ground_truth_accuracy(),
        }

