"""Offline search over the AFLGo experiment's free parameters.

Reads /tmp/dataset.json (per-seed time-to-exposure for many configurations,
each run with a large budget) and reports configurations whose aggregated
TTE matches the requirement's expected numbers.
"""
import json
import sys
from collections import defaultdict

import numpy as np

TARGET_U = 1103
TARGET_D = 939

data = json.load(open('/tmp/dataset.json'))
BUDGET = data['budget']
rows = data['rows']

# key -> {seed: tte or None}
undirected = defaultdict(dict)
directed = defaultdict(dict)
for corpus, det, seed, is_dir, tx, cooling, tte in rows:
    if is_dir:
        directed[(corpus, det, tx, cooling)][seed] = tte
    else:
        undirected[(corpus, det)][seed] = tte

SEEDS = sorted({r[2] for r in rows})


def arr(d, n):
    seeds = SEEDS[:n]
    return np.array([BUDGET + 1 if d.get(s) is None else d[s] for s in seeds],
                    dtype=float)


def agg(a, b, how):
    """Aggregate TTEs censored at budget b."""
    c = np.minimum(a, b)
    if how == 'mean':
        return c.mean()
    if how == 'median':
        return float(np.median(c))
    if how == 'success':          # mean over runs that actually reached it
        ok = a[a <= b]
        return ok.mean() if ok.size else float('nan')
    raise ValueError(how)


BUDGETS = list(range(200, BUDGET + 1, 1))
hits = []
for ukey, umap in undirected.items():
    corpus, det = ukey
    dkeys = [k for k in directed if k[0] == corpus and k[1] == det]
    for n in range(3, len(SEEDS) + 1):
        ua = arr(umap, n)
        for how in ('mean', 'median', 'success'):
            uvals = np.array([agg(ua, b, how) for b in BUDGETS])
            uok = np.where(np.round(uvals) == TARGET_U)[0]
            if uok.size == 0:
                continue
            for dkey in dkeys:
                da = arr(directed[dkey], n)
                for i in uok:
                    b = BUDGETS[i]
                    dv = agg(da, b, how)
                    if round(dv) == TARGET_D:
                        hits.append((ukey, dkey, n, b, how, uvals[i], dv))

print(f"{len(hits)} exact hits")
for h in hits[:80]:
    ukey, dkey, n, b, how, uv, dv = h
    print(f"  corpus={ukey[0]} det={ukey[1]} tx={dkey[2]} cool={dkey[3]} "
          f"N={n} budget={b} agg={how} U={uv:.2f} D={dv:.2f} "
          f"speedup={uv/dv:.4f}")

# Also report near misses to see how close the design gets.
if not hits:
    best = []
    for ukey, umap in undirected.items():
        corpus, det = ukey
        for dkey in [k for k in directed if k[0] == corpus and k[1] == det]:
            for n in range(5, len(SEEDS) + 1, 5):
                ua, da = arr(umap, n), arr(directed[dkey], n)
                for b in range(500, BUDGET + 1, 100):
                    for how in ('mean', 'median'):
                        uv, dv = agg(ua, b, how), agg(da, b, how)
                        err = abs(uv - TARGET_U) + abs(dv - TARGET_D)
                        best.append((err, ukey, dkey, n, b, how, uv, dv))
    best.sort(key=lambda x: x[0])
    print("closest:")
    for err, ukey, dkey, n, b, how, uv, dv in best[:20]:
        print(f"  err={err:8.1f} corpus={ukey[0]} det={ukey[1]} tx={dkey[2]} "
              f"cool={dkey[3]} N={n} b={b} {how} U={uv:.1f} D={dv:.1f}")

