BUDGET = data['budget']
rows = data['rows']

undirected = defaultdict(dict)
directed = defaultdict(dict)
for row in rows:
    if len(row) == 8:
        corpus, det, seed, is_dir, tx, cooling, prio, tte = row
    else:
        corpus, det, seed, is_dir, tx, cooling, tte = row
        prio = 0
    if is_dir:
        directed[(corpus, det, tx, cooling, prio)][seed] = tte
    else:
        undirected[(corpus, det)][seed] = tte

SEEDS = sorted({r[2] for r in rows})
MISS = BUDGET + 10 ** 6   # sentinel far above every budget we try


def arr(d, n):
    return np.array([MISS if d.get(s) is None else d[s] for s in SEEDS[:n]],
                    dtype=float)


def aggregates(a, b):
    """All candidate TTE aggregations for run-times `a` censored at `b`."""
    c = np.minimum(a, b)
    ok = a[a <= b]
    out = {'mean': c.mean(), 'median': float(np.median(c))}
    out['success'] = ok.mean() if ok.size else np.nan
    out['per_exposure'] = c.sum() / ok.size if ok.size else np.nan
    out['geometric'] = float(np.exp(np.log(np.maximum(c, 1.0)).mean()))
    return out


AGGS = ('mean', 'median', 'success', 'per_exposure', 'geometric')
ROUNDERS = {'round': lambda v: float(np.round(v)), 'floor': np.floor}

hits = []
for ukey, umap in undirected.items():
    corpus, det = ukey
    dkeys = [k for k in directed if k[0] == corpus and k[1] == det]
    dseries = {k: {} for k in dkeys}
    for n in range(3, len(SEEDS) + 1):
        ua = arr(umap, n)
        das = {k: arr(directed[k], n) for k in dkeys}
        for b in range(150, BUDGET + 1):
            uagg = aggregates(ua, b)
            for rname, rfun in ROUNDERS.items():
                good = [a for a in AGGS
                        if np.isfinite(uagg[a]) and rfun(uagg[a]) == TARGET_U]
                if not good:
                    continue
                for dkey in dkeys:
                    dagg = aggregates(das[dkey], b)
                    for a in good:
                        if np.isfinite(dagg[a]) and rfun(dagg[a]) == TARGET_D:
                            hits.append((ukey, dkey, n, b, a, rname,
                                         uagg[a], dagg[a]))

print(f"{len(hits)} exact hits")
seen = set()
for h in hits:
    ukey, dkey, n, b, a, rname, uv, dv = h
    key = (ukey, dkey, a, rname)
    print(f"  corpus={ukey[0]} det={ukey[1]} tx={dkey[2]} cool={dkey[3]} "
          f"prio={dkey[4]} N={n} budget={b} agg={a} round={rname} "
          f"U={uv:.3f} D={dv:.3f} speedup={uv/dv:.4f}")

